package main

import (
	"bytes"
	"encoding/json"
	"io/ioutil"
	"os"
	"strconv"
	"testing"
)

// setUpTest prepares the test environment
func setUpTest() func() {
	// Clean up any existing tasks.json
	os.Remove(tasksFile)

	// Capture stdout
	oldStdout := os.Stdout
	r, w, _ := os.Pipe()
	os.Stdout = w

	return func() {
		// Restore stdout
		w.Close()
		os.Stdout = oldStdout
		// Clean up tasks.json after test
		os.Remove(tasksFile)
		// Reset os.Args
		os.Args = []string{"todo"}
	}
}

// captureOutput reads the captured stdout
func captureOutput(r *os.File) string {
	w.Close()
	out, _ := ioutil.ReadAll(r)
	return string(out)
}

// TestAddCommand tests the add command
func TestAddCommand(t *testing.T) {
	teardown := setUpTest()
	defer teardown()

	// Mock os.Args for add command
	os.Args = []string{"todo", "add", "Buy milk"}

	// Capture stdout for main function
	oldStdout := os.Stdout
	r, w, _ := os.Pipe()
	os.Stdout = w

	main()

	output := captureOutput(r)

	expected := map[string]interface{}{"id": float64(1), "status": "added"}
	var actual map[string]interface{}
	if err := json.Unmarshal([]byte(output), &actual); err != nil {
		t.Fatalf("Failed to unmarshal output: %v, output: %s", err, output)
	}

	if actual["id"] != expected["id"] || actual["status"] != expected["status"] {
		t.Errorf("Expected %v, got %v", expected, actual)
	}

	// Verify task is in tasks.json
	tasks, err := loadTasks()
	if err != nil {
		t.Fatalf("Failed to load tasks after add: %v", err)
	}
	if len(tasks) != 1 || tasks[0].Description != "Buy milk" || tasks[0].ID != 1 || tasks[0].Done != false {
		t.Errorf("Task not saved correctly: %v", tasks)
	}
}

// TestListCommand tests the list command
func TestListCommand(t *testing.T) {
	teardown := setUpTest()
	defer teardown()

	// Add a task first
	testTasks := []Task{{"ID": 1, "Description": "Buy bread", "Done": false}}
	saveTasks(testTasks)

	// Mock os.Args for list command
	os.Args = []string{"todo", "list"}

	// Capture stdout
	oldStdout := os.Stdout
	r, w, _ := os.Pipe()
	os.Stdout = w

	main()

	output := captureOutput(r)

	expected := `[{"id":1,"description":"Buy bread","done":false}]`
	if strings.TrimSpace(output) != expected {
		t.Errorf("Expected %s, got %s", expected, strings.TrimSpace(output))
	}
}

// TestDoneCommand tests the done command
func TestDoneCommand(t *testing.T) {
