// TestErrorHandlingInvalidArgs tests invalid arguments for add command
func TestErrorHandlingInvalidAddArgs(t *testing.T) {
	teardown := setUpTest()
	defer teardown()

	// Mock os.Args for add command with missing description
	os.Args = []string{"todo", "add"}

	// Capture stdout and stderr, and exit code
	oldStdout := os.Stdout
	oldStderr := os.Stderr
	oldExit := os.Exit

	var buf bytes.Buffer
	w := bytes.NewBuffer(nil)
	os.Stdout = os.Stderr // Redirect stdout to stderr for error messages
	os.Stderr = w
	exitCode := 0
	os.Exit = func(code int) {
		exitCode = code
		panic("os.Exit was called") // Panic to stop execution without exiting test runner
	}

	defer func() {
		os.Stdout = oldStdout
		os.Stderr = oldStderr
		os.Exit = oldExit
		// Recover from panic caused by os.Exit
		if r := recover(); r != nil && r != "os.Exit was called" {
			t.Fatalf("Unexpected panic: %v", r)
		}
	}()

	main()

	output := strings.TrimSpace(w.String())
	expected := `{"error":"invalid arguments"}`

	if output != expected {
		t.Errorf("Expected error output %s, got %s", expected, output)
	}
	if exitCode != 42 {
		t.Errorf("Expected exit code 42, got %d", exitCode)
	}
}

