// TestLoadSaveTasks tests loading and saving tasks
func TestLoadSaveTasks(t *testing.T) {
	teardown := setUpTest()
	defer teardown()

	tasks := []Task{
		{ID: 1, Description: "Task 1", Done: false},
		{ID: 2, Description: "Task 2", Done: true},
	}

	err := saveTasks(tasks)
	if err != nil {
		t.Fatalf("Failed to save tasks: %v", err)
	}

	loadedTasks, err := loadTasks()
	if err != nil {
		t.Fatalf("Failed to load tasks: %v", err)
	}

	if len(loadedTasks) != len(tasks) {
		t.Fatalf("Expected %d tasks, got %d", len(tasks), len(loadedTasks))
	}

	for i, task := range tasks {
		if loadedTasks[i].ID != task.ID || loadedTasks[i].Description != task.Description || loadedTasks[i].Done != task.Done {
			t.Errorf("Mismatch in loaded task at index %d. Expected %v, got %v", i, task, loadedTasks[i])
		}
	}
}

