	os.Args = []string{"todo", "add", "First task"}
	main()

	// Add second task
	os.Args = []string{"todo", "add", "Second task"}
	main()

	// Load tasks and check IDs
	tasks, err := loadTasks()
	if err != nil {
		t.Fatalf("Failed to load tasks: %v", err)
	}

	if len(tasks) != 2 {
		t.Fatalf("Expected 2 tasks, got %d", len(tasks))
	}

	if tasks[0].ID != 1 || tasks[1].ID != 2 {
		t.Errorf("Expected IDs 1, 2; got %d, %d", tasks[0].ID, tasks[1].ID)
	}
}

// TestNextIDGenerationWithGaps ensures IDs are unique and increment even with gaps
func TestNextIDGenerationWithGaps(t *testing.T) {
	teardown := setUpTest()
	defer teardown()

	// Manually add tasks with a gap
	initialTasks := []Task{
		{ID: 1, Description: "Task one", Done: false},
		{ID: 3, Description: "Task three", Done: false},
	}
	saveTasks(initialTasks)

	// Add a new task, should get ID 4
	os.Args = []string{"todo", "add", "Task four"}
	main()

	tasks, err := loadTasks()
	if err != nil {
		t.Fatalf("Failed to load tasks: %v", err)
	}

	if len(tasks) != 3 {
		t.Fatalf("Expected 3 tasks, got %d", len(tasks))
	}

	var newID int
	for _, task := range tasks {
		if task.Description == "Task four" {
			newID = task.ID
			break
		}
	}

	if newID != 4 {
		t.Errorf("Expected new task ID to be 4, got %d", newID)
	}
}

