package main

import (
	"bytes"
	"encoding/json"
	"io/ioutil"
	"os"
	"strconv"
	"strings"
	"sync"
	"testing"
)

// A global variable to store the original os.Stderr for cleanup
var originalStderr *os.File
var originalStdout *os.File

// Helper to capture os.Stdout
func captureStdout(f func()) string {
	var buf bytes.Buffer
	oldStdout := os.Stdout
	defer func() {
		os.Stdout = oldStdout
	}()
	os.Stdout = os.NewFile(0, "/dev/stdout")
	// Use a pipe to capture stdout
	r, w, _ := os.Pipe()
	os.Stdout = w

	// Run the function that writes to stdout
	f()

	w.Close()
	out, _ := ioutil.ReadAll(r)
	return string(out)
}

// Helper to capture os.Stderr and os.Exit
func captureStderrAndExit(f func(), expectedExitCode int) (string, int) {
	var buf bytes.Buffer
	oldStderr := os.Stderr
	oldStdout := os.Stdout // Also capture stdout to prevent clutter
	oldExit := os.Exit
	exitCode := 0

	// Redirect os.Stderr to our buffer
	// Use a pipe to capture stderr
	r, w, _ := os.Pipe()
	os.Stderr = w
	os.Stdout = w // Redirect stdout to stderr for error messages

	os.Exit = func(code int) {
		exitCode = code
