package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"strconv"
	"strings"
)

const (
	tasksFile = "tasks.json"
)

// osExit is a package-level variable that can be swapped for testing
var osExit = os.Exit

// Task represents a single todo item
type Task struct {
	ID          int    `json:"id"`
	Description string `json:"description"`
	Done        bool   `json:"done"`
}

// loadTasks loads tasks from tasks.json
func loadTasks() ([]Task, error) {
	data, err := ioutil.ReadFile(tasksFile)
	if err != nil {
		if os.IsNotExist(err) {
			return []Task{}, nil // Return empty list if file doesn't exist
		}
		return nil, fmt.Errorf("failed to read tasks file: %w", err)
	}

	var tasks []Task
	if err := json.Unmarshal(data, &tasks); err != nil {
		return nil, fmt.Errorf("failed to unmarshal tasks: %w", err)
	}
	return tasks, nil
}

// saveTasks saves tasks to tasks.json
func saveTasks(tasks []Task) error {
	data, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal tasks: %w", err)
	}

	if err := ioutil.WriteFile(tasksFile, data, 0644); err != nil {
		return fmt.Errorf("failed to write tasks file: %w", err)
	}
	return nil
}

// printError prints an error message in JSON format and exits
func printError(msg string, code int) {
	output := map[string]string{"error": msg}
	jsonOutput, _ := json.Marshal(output)
	fmt.Println(string(jsonOutput))
	osExit(code)
}

func main() {
	if len(os.Args) < 2 {
		printError("invalid arguments", 42)
	}

	command := os.Args[1]

	switch command {
	case "add":
		handleAdd()
	case "list":
		handleList()
	case "done":
		handleDone()
	default:
		printError("unknown command", 42)
	}
}

func handleAdd() {
	if len(os.Args) < 3 || strings.TrimSpace(os.Args[2]) == "" {
		printError("invalid arguments", 42)
	}
	description := os.Args[2]

	tasks, err := loadTasks()
	if err != nil {
		printError(err.Error(), 1)
	}

	nextID := 1
	if len(tasks) > 0 {
		for _, task := range tasks {
			if task.ID >= nextID {
				nextID = task.ID + 1
			}
		}
	}

	newTask := Task{
		ID:          nextID,
		Description: description,
		Done:        false,
	}
	tasks = append(tasks, newTask)

	if err := saveTasks(tasks); err != nil {
		printError(err.Error(), 1)
	}

	result := map[string]interface{}{"id": newTask.ID, "status": "added"}
	jsonOutput, _ := json.Marshal(result)
	fmt.Println(string(jsonOutput))
}

func handleList() {
	tasks, err := loadTasks()
	if err != nil {
		printError(err.Error(), 1)
	}

	var pendingTasks []Task
	for _, task := range tasks {
		if !task.Done {
			pendingTasks = append(pendingTasks, task)
		}
	}

	jsonOutput, _ := json.Marshal(pendingTasks)
	fmt.Println(string(jsonOutput))
}

func handleDone() {
	if len(os.Args) < 3 || strings.TrimSpace(os.Args[2]) == "" {
		printError("invalid arguments", 42)
	}

	idStr := os.Args[2]
	id, err := strconv.Atoi(idStr)
	if err != nil {
		printError("invalid task ID", 42)
	}

	tasks, err := loadTasks()
	if err != nil {
		printError(err.Error(), 1)
	}

	found := false
	for i := range tasks {
		if tasks[i].ID == id {
			tasks[i].Done = true
			found = true
			break
		}
	}

	if !found {
		printError(fmt.Sprintf("task with ID %d not found", id), 42)
	}

	if err := saveTasks(tasks); err != nil {
		printError(err.Error(), 1)
	}

	result := map[string]interface{}{"id": id, "status": "completed"}
	jsonOutput, _ := json.Marshal(result)
	fmt.Println(string(jsonOutput))
}

