// Helper to capture os.Stdout
func captureStdout(f func()) string {
	oldStdout := os.Stdout
	defer func() {
		os.Stdout = oldStdout
	}()

	r, w, _ := os.Pipe()
	os.Stdout = w

	f()

w.Close()
	out, _ := ioutil.ReadAll(r)
	return string(out)
}

// Helper to capture os.Stderr and os.Exit
func captureStderrAndExit(f func(), expectedExitCode int) (string, int) {
	oldStderr := os.Stderr
	oldStdout := os.Stdout // Also capture stdout to prevent clutter
	oldOsExit := osExit // Store the original osExit function
	exitCode := 0

	r, w, _ := os.Pipe()
	os.Stderr = w
	os.Stdout = w // Redirect stdout to stderr for error messages

	osExit = func(code int) {
		exitCode = code
		panic("os.Exit was called") // Panic to stop execution without exiting test runner
	}

	defer func() {
		// Restore os.Stderr, os.Stdout and osExit
		os.Stderr = oldStderr
		os.Stdout = oldStdout
		osExit = oldOsExit
		w.Close()
		// Recover from panic caused by os.Exit
		if r := recover(); r != nil && r != "os.Exit was called" {
			// If the panic was not from os.Exit, re-panic
			panic(r)
		}
	}()

	f()

	out, _ := ioutil.ReadAll(r)
	return strings.TrimSpace(string(out)), exitCode
}

