// Helper to capture os.Stdout
func captureStdout(f func()) string {
	oldStdout := os.Stdout
	defer func() {
		os.Stdout = oldStdout
	}()

	r, w, _ := os.Pipe()
	os.Stdout = w

	f()

w.Close()
	out, _ := ioutil.ReadAll(r)
	return string(out)
}

// Helper to capture os.Stderr and os.Exit
func captureStderrAndExit(f func(), expectedExitCode int) (string, int) {
	oldStderr := os.Stderr
	oldStdout := os.Stdout // Also capture stdout to prevent clutter
	oldOsExit := osExit   // Store the original osExit function
	exitCode := 0

	var outputBuffer bytes.Buffer

	// Redirect os.Stdout and os.Stderr to our buffer
	os.Stdout = os.NewFile(0, "/dev/stdout") // Re-assigning to a dummy file to avoid nil dereference later if tests don't restore
	os.Stderr = os.NewFile(0, "/dev/stderr")

	syscallStdout := os.Stdout
	syscallStderr := os.Stderr

	r, w, _ := os.Pipe()
	os.Stdout = w
	os.Stderr = w

	osExit = func(code int) {
		exitCode = code
		// Before panicking, ensure all output is flushed and captured
		w.Close()
		out, _ := ioutil.ReadAll(r)
		outputBuffer.Write(out)
		panic("os.Exit was called") // Panic to stop execution without exiting test runner
	}

	defer func() {
		// Restore os.Stderr, os.Stdout and osExit
		os.Stderr = oldStderr
		os.Stdout = oldStdout
		osExit = oldOsExit
		// Recover from panic caused by os.Exit
		if r := recover(); r != nil && r != "os.Exit was called" {
			// If the panic was not from os.Exit, re-panic
			panic(r)
		}
	}()

	f()

	// In case osExit was not called, we still need to capture any lingering output
	w.Close()
	out, _ := ioutil.ReadAll(r)
	outputBuffer.Write(out)

	return strings.TrimSpace(outputBuffer.String()), exitCode
}

