// Helper to capture os.Stdout
func captureStdout(f func()) string {
	oldStdout := os.Stdout
	defer func() {
		os.Stdout = oldStdout
	}()

	r, w, _ := os.Pipe()
	os.Stdout = w

	f()

w.Close()
	out, _ := ioutil.ReadAll(r)
	return string(out)
}

// Helper to capture os.Stderr and os.Exit
func captureStderrAndExit(f func(), expectedExitCode int) (string, int) {
	oldStderr := os.Stderr
	oldStdout := os.Stdout
	oldOsExit := osExit

	var outputBuffer bytes.Buffer

	// Create a new File for stdout and stderr that writes to our buffer
	// This requires creating a new os.File from a pipe that writes to the buffer
	// For simplicity, we'll use an in-memory buffer directly if possible.
	// However, fmt.Println expects an *os.File, so we need a workaround.
	// The safest way is to use a pipe and ensure it's read.

	rPipe, wPipe, _ := os.Pipe()
	os.Stdout = wPipe
	os.Stderr = wPipe

	exitCode := 0
	osExit = func(code int) {
		exitCode = code
		wPipe.Close()
		out, _ := ioutil.ReadAll(rPipe)
		outputBuffer.Write(out)
		panic("os.Exit was called")
	}

	defer func() {
		// Restore original stdout/stderr/osExit
		os.Stdout = oldStdout
		os.Stderr = oldStderr
		osExit = oldOsExit

		// Ensure pipe is closed if osExit was not called (e.g. no panic)
		rPipe.Close()
		wPipe.Close()

		// Recover from panic caused by os.Exit
		if r := recover(); r != nil && r != "os.Exit was called" {
			panic(r)
		}
	}()

	f()

	// If the function completes without calling osExit, ensure output is read
	wPipe.Close()
	out, _ := ioutil.ReadAll(rPipe)
	outputBuffer.Write(out)

	return strings.TrimSpace(outputBuffer.String()), exitCode
}

