// Helper to capture os.Stdout
func captureStdout(f func()) string {
	oldStdout := os.Stdout
	defer func() {
		os.Stdout = oldStdout
	}()

	r, w, _ := os.Pipe()
	os.Stdout = w

	f()

w.Close()
	out, _ := ioutil.ReadAll(r)
	return string(out)
}

// Helper to capture os.Stderr and os.Exit
func captureStderrAndExit(f func(), expectedExitCode int) (string, int) {
	oldStderr := os.Stderr
	oldStdout := os.Stdout
	oldOsExit := osExit

	var outputBuffer bytes.Buffer
	var wg sync.WaitGroup

	r, w, _ := os.Pipe()

	// Redirect os.Stdout and os.Stderr to the pipe writer
	os.Stdout = w
	os.Stderr = w

	wg.Add(1)
	go func() {
		defer wg.Done()
		io.Copy(&outputBuffer, r)
	}()

	exitCode := 0
	osExit = func(code int) {
		exitCode = code
		// Close the writer end of the pipe to signal the goroutine to finish
		w.Close()
		wg.Wait() // Wait for the goroutine to finish reading
		panic("os.Exit was called")
	}

	defer func() {
		// Restore original stdout/stderr/osExit
		os.Stdout = oldStdout
		os.Stderr = oldStderr
		osExit = oldOsExit

		// If osExit was not called, we need to manually close the pipe and wait for the goroutine
		if r := recover(); r != nil {
			// If the panic was not from os.Exit, re-panic
			if r != "os.Exit was called" {
				panic(r)
			}
		} else {
			// If no panic, means osExit was not called.
			w.Close()
			wg.Wait()
		}
	}()

	f()

	return strings.TrimSpace(outputBuffer.String()), exitCode
}

